solution.solution.cpp:
#include <algorithm>
#include <string>
#include <vector>

struct Threat
{
    std::string name;
    int likelihood;
    int impact;
    int cost;          // estimated days to fix
    bool accepted;
};

std::vector<std::string> rankThreats(const std::vector<Threat>& threats)
{
    auto valid = [](int v) { return v >= 1 && v <= 5; };
    std::vector<Threat> kept;
    for (const Threat& t : threats)
        if (!t.accepted && valid(t.likelihood) && valid(t.impact)) kept.push_back(t);

    std::sort(kept.begin(), kept.end(), [](const Threat& a, const Threat& b) {
        const int sa{ a.likelihood * a.impact };
        const int sb{ b.likelihood * b.impact };
        if (sa != sb) return sa > sb;
        if (a.cost != b.cost) return a.cost < b.cost;
        return a.name < b.name;
    });

    std::vector<std::string> names;
    for (const Threat& t : kept) names.push_back(t.name);
    return names;
}

unitTests:
TEST("by score")
{
    const auto r{ rankThreats({ { "flood", 3, 2, 1, false }, { "fake score", 4, 4, 5, false }, { "path", 2, 5, 1, false } }) };
    CHECK_EQ(r.size(), std::size_t{ 3 });
    CHECK_EQ(r[0], std::string("fake score"));
    CHECK_EQ(r[1], std::string("path"));
    CHECK_EQ(r[2], std::string("flood"));
}
TEST("cheaper first on a tie") { const auto r{ rankThreats({ { "a", 2, 3, 4, false }, { "b", 3, 2, 1, false } }) }; CHECK_EQ(r[0], std::string("b")); }
TEST("then by name") { const auto r{ rankThreats({ { "zeta", 2, 2, 1, false }, { "alpha", 4, 1, 1, false } }) }; CHECK_EQ(r[0], std::string("alpha")); CHECK_EQ(r[1], std::string("zeta")); }
TEST("accepted threats are left out") { const auto r{ rankThreats({ { "save edit", 5, 1, 1, true }, { "xss", 3, 4, 1, false } }) }; CHECK_EQ(r.size(), std::size_t{ 1 }); CHECK_EQ(r[0], std::string("xss")); }
TEST("invalid ratings are left out") { CHECK(rankThreats({ { "x", 0, 3, 1, false }, { "y", 3, 6, 1, false } }).empty()); }
TEST("empty") { CHECK(rankThreats({}).empty()); }

